/* Customer workspace. Local demonstration workflows; no external submissions. */
window.SHCustomer=(()=>{
 const pages=['Inspections','Variations','Project documents','Tender scope'];
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const id=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
 function init(c){for(const k of ['inspections','variations','documents','tenderScopes','tenderOptions'])if(!Array.isArray(c.store[k]))c.store[k]=[];c.store.fees??={};}
 const pid=c=>c.projectId||c.project?.id||c.projects?.[0]?.id;
 const rows=(c,k)=>c.store[k].filter(x=>x.projectId===pid(c));
 const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const area=(name,label,value='')=>`<label>${esc(label)}<textarea name="${name}" rows="3" maxlength="5000">${esc(value)}</textarea></label>`;
 function render(page,c){init(c);if(!pages.includes(page))return '';const project=c.project||c.projects?.find(p=>p.id===pid(c));let body='';
 if(page==='Inspections')body=`<div class="customer-notice"><strong>Check before the next stage</strong><p>Map hold points to the actual building consent and council inspection requirements. The example below is a planning aid, not an approved inspection schedule. A recorded result does not constitute council approval.</p></div><section class="card"><h2>Inspection hold points</h2>${rows(c,'inspections').map(x=>`<article class="customer-item"><h3>${esc(x.name)}</h3><p>Before: <strong>${esc(x.nextStage)}</strong> · Consent reference: ${esc(x.reference||'Not mapped')}</p><span class="tag ${x.status==='Recorded pass'?'':'amber'}">${esc(x.status)}</span><p>Evidence: ${esc(x.evidence||'Awaiting inspection evidence')}</p><button class="secondary" data-inspect="${esc(x.id)}">Record inspection result</button></article>`).join('')||'<p>No consent hold points mapped yet. Add the first requirement from your approved consent.</p>'}</section><form class="card customer-form" id="inspectionForm"><h2>Add a consent hold point</h2>${field('name','Inspection requirement (example: pre-pour)', '', 'text','required maxlength="150"')}${field('nextStage','Stage that must wait', '', 'text','required maxlength="150"')}${field('reference','Actual consent / schedule reference', '', 'text','required maxlength="200"')}${field('due','Planned inspection date','','date','required')}<p class="small">This creates a local reminder for all project roles. Stage release remains subject to actual consent conditions and verified evidence.</p><button class="primary">Save hold point & notify</button></form>`;
 if(page==='Variations')body=`<div class="customer-notice"><strong>Changes start with a request</strong><p>Scope, cost and programme changes must be assessed and agreed before work proceeds. Notifications stay in this browser preview.</p></div><form class="card customer-form" id="variationForm"><h2>Request a project variation</h2>${field('title','Change title','','text','required maxlength="150"')}${area('description','Requested scope and reason')}${field('costImpact','Expected cost impact / unknown','','text','required maxlength="200"')}${field('timeImpact','Expected time impact / unknown','','text','required maxlength="200"')}<button class="primary">Send request to project parties</button></form><section class="card"><h2>Variation register</h2>${rows(c,'variations').map(x=>`<article class="customer-item"><h3>${esc(x.title)}</h3><span class="tag amber">${esc(x.status)}</span><p>${esc(x.description)}</p><p>Cost: ${esc(x.costImpact)} · Time: ${esc(x.timeImpact)}</p>${x.assessment?`<p>Assessment: ${esc(x.assessment)}</p>`:''}${x.status==='customer approval'?`<button class="primary" data-approve="${esc(x.id)}">Approve assessed scope, cost & time</button><button class="secondary" data-reject="${esc(x.id)}">Return for assessment</button>`:'<p class="small">Shed House and the contractor assess the request before customer approval. Approval does not automatically start work.</p>'}</article>`).join('')||'<p>No variation requests for this project.</p>'}</section>`;
 if(page==='Project documents')body=`<section class="card"><h2>Your shared project library</h2><p>Documents added by Shed House appear here when shared with Customer. Check the revision and approval status before using a document for construction.</p>${rows(c,'documents').filter(d=>Array.isArray(d.visibility)&&d.visibility.includes('customer')).map(d=>{let url='';try{const u=new URL(d.url);if(['https:','http:'].includes(u.protocol))url=u.href;}catch{}return `<article class="customer-item"><h3>${esc(d.name)}</h3><p>${esc(d.type)} · Version ${esc(d.version||'Unspecified')} · ${esc(d.status||'Unreviewed')}</p><p class="small">Added ${esc(d.uploadedAt||'Date not recorded')}</p>${url?`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open document ↗</a>`:'<span class="small">No valid document link supplied</span>'}</article>`;}).join('')||'<p>No customer documents shared yet. Shed House can add plans, specifications and consent documents to this project.</p>'}</section>`;
 if(page==='Tender scope'){const s=rows(c,'tenderScopes')[0]||{};const fee=c.store.fees.customerTender;body=`<div class="customer-notice"><strong>Define the work before inviting prices</strong><p>A clear scope helps builders price the same package. Confirm consent conditions and responsibilities with your project team.</p></div><form class="card customer-form" id="scopeForm"><h2>Customer → contractor scope</h2><p>Revision ${esc(s.version||0)} · ${esc(s.status||'Draft')}</p>${area('inclusions','Included work',s.inclusions)}${area('exclusions','Excluded work',s.exclusions)}${area('responsibilities','Customer / Shed House / contractor responsibilities',s.responsibilities)}${area('siteAccess','Site access, services and constraints',s.siteAccess)}${area('consentReferences','Consent and inspection references',s.consentReferences)}${area('specification','Specification and drawing revisions',s.specification)}${area('acceptance','Completion and acceptance requirements',s.acceptance)}<label class="customer-check"><input type="checkbox" name="tenderSelected" ${c.store.tenderOptions.some(x=>x.projectId===pid(c)&&x.selected)?'checked':''}> Optional nationwide builder tender service</label><p>${fee==null?'Fee awaiting Shed House configuration. Selection records interest only.':`One-off configured fee: ${esc(c.money?c.money(fee):`NZD ${fee}`)}. GST basis must be confirmed by Shed House.`} No payment is taken.</p><label class="customer-check"><input type="checkbox" name="confirm" required> I have reviewed these scope requirements for tender preparation.</label><button class="primary">Save scope revision</button></form>`;}
 return `<div class="customer-workspace"><div class="heading"><div><div class="eyebrow">CUSTOMER WORKSPACE · LOCAL DEMO</div><h1>${esc(page)}</h1><p>${esc(project?.name||'Your project')} · ${esc(pid(c)||'No project selected')}</p></div></div>${body}</div>`;}
 function bind(page,c){init(c);const save=()=>{c.save();c.navigate(page);};const notify=(title,message,kind)=>c.notify({title,message,roles:['staff','customer','contractor'],projectId:pid(c),kind});
 const form=document.getElementById('inspectionForm');if(form)form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));c.store.inspections.push({...f,id:id(),projectId:pid(c),status:'Hold — inspection required',createdAt:new Date().toISOString()});notify('Inspection hold point added',`${f.name} is required before ${f.nextStage}. Planned ${f.due}; confirm booking with the council.`,'inspection');save();};
 document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{const x=rows(c,'inspections').find(v=>v.id===b.dataset.inspect);const result=prompt('Record result: pass, fail, or pending. This does not verify council approval.','pending');if(result===null)return;if(!['pass','fail','pending'].includes(result.toLowerCase()))return c.toast('Enter pass, fail, or pending');const evidence=prompt('Record evidence reference, inspector and date. Required for a pass.','');if(evidence===null)return;if(result.toLowerCase()==='pass'&&!evidence.trim())return c.toast('Evidence is required for a recorded pass');x.status=result.toLowerCase()==='pass'?'Recorded pass':result.toLowerCase()==='fail'?'Hold — recorded fail':'Hold — pending';x.evidence=evidence;x.recordedAt=new Date().toISOString();notify('Inspection result recorded',`${x.name}: ${x.status}. Verify consent requirements before continuing.`,'inspection');save();});
 const variation=document.getElementById('variationForm');if(variation)variation.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(variation));if(!f.description.trim())return c.toast('Describe the requested scope');c.store.variations.push({...f,id:id(),projectId:pid(c),status:'requested',createdAt:new Date().toISOString(),requestedBy:'customer'});notify('Customer variation requested',`${f.title}: scope, cost and time assessment required before work.`,'variation');save();};
 document.querySelectorAll('[data-approve],[data-reject]').forEach(b=>b.onclick=()=>{const x=rows(c,'variations').find(v=>v.id===(b.dataset.approve||b.dataset.reject));if(!x||x.status!=='customer approval')return;if(b.dataset.approve&&!confirm(`Approve ${x.title}? Cost: ${x.costImpact}. Time: ${x.timeImpact}. Assessment: ${x.assessment||'Not provided'}`))return;x.status=b.dataset.approve?'approved work':'assessment';x.customerDecisionAt=new Date().toISOString();notify('Variation decision recorded',`${x.title}: ${x.status}. Project parties must coordinate the agreed next step.`,'variation');save();});
 const scope=document.getElementById('scopeForm');if(scope)scope.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(scope));const old=rows(c,'tenderScopes')[0];const data={...f,id:old?.id||id(),projectId:pid(c),version:(Number(old?.version)||0)+1,status:'Customer reviewed',updatedAt:new Date().toISOString()};if(old)Object.assign(old,data);else c.store.tenderScopes.push(data);let option=rows(c,'tenderOptions')[0];if(!option){option={id:id(),projectId:pid(c)};c.store.tenderOptions.push(option);}Object.assign(option,{selected:f.tenderSelected==='on',feeSnapshot:c.store.fees.customerTender??null,status:'Interest only — no payment',updatedAt:data.updatedAt});notify('Tender scope revised',`Customer scope revision ${data.version} saved. Review changes before tender issue.`,'scope');save();};
 }
 return {pages,render,bind};
})();
